import zipfile

# Read BUSCO summary text files for all species
for bzip in ['Animals_Cele.busco.zip', 'Animals_Ggal.busco.zip', 'Animals_Mmus.busco.zip', 
             'Animals_Xlae.busco.zip', 'Fungi_Ncra.busco.zip', 'Fungi_Scer.busco.zip',
             'Fungi_Spom.busco.zip', 'Fungi_Umay.busco.zip']:
    with zipfile.ZipFile(bzip) as z:
        txt = [n for n in z.namelist() if n.endswith('.busco.txt')]
        if txt:
            content = z.read(txt[0]).decode('utf-8')
            # Print just the summary line
            for line in content.split('\n'):
                if 'C:' in line or 'Results:' in line or line.strip().startswith('C:'):
                    print(f"{bzip}: {line.strip()}")
